package br.com.helptech.v3;
import android.app.*;import android.os.*;import android.content.*;import android.webkit.*;import androidx.webkit.WebViewAssetLoader;import org.json.*;
public class MainActivity extends Activity {
 WebView view;String attendedId;
 @Override public void onCreate(Bundle b){super.onCreate(b);view=new WebView(this);view.getSettings().setJavaScriptEnabled(true);view.getSettings().setDomStorageEnabled(true);view.addJavascriptInterface(new Object(){@JavascriptInterface public void schedule(String json){runOnUiThread(()->{try{JSONArray a=new JSONArray(json);getSharedPreferences("alarms",0).edit().putString("jobs",json).apply();for(int n=0;n<a.length();n++){JSONObject j=a.getJSONObject(n);String id=j.getString("id");if(getSharedPreferences("attended",0).getBoolean(id,false))continue;long at=java.time.LocalDateTime.parse(j.getString("date")+"T"+j.getString("time")).atZone(java.time.ZoneId.systemDefault()).toInstant().toEpochMilli()-3600000;if(at>System.currentTimeMillis())AlarmReceiver.set(MainActivity.this,id,j.optString("client"),j.optString("service"),j.optString("address"),at);}}catch(Exception e){android.util.Log.e("HelpTech","Alarm schedule",e);}});}},"HelpTechAlarm");WebViewAssetLoader loader=new WebViewAssetLoader.Builder().addPathHandler("/assets/",new WebViewAssetLoader.AssetsPathHandler(this)).build();view.setWebViewClient(new WebViewClient(){@Override public android.webkit.WebResourceResponse shouldInterceptRequest(WebView v,android.webkit.WebResourceRequest r){return loader.shouldInterceptRequest(r.getUrl());}@Override public void onPageFinished(WebView v,String u){applyAttended();}});setContentView(view);attendedId=getIntent().getStringExtra("attended_id");view.loadUrl("https://appassets.androidplatform.net/assets/index.html");if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},3);}
 void applyAttended(){if(attendedId!=null){view.evaluateJavascript("window.helpTechMarkAttended&&window.helpTechMarkAttended("+JSONObject.quote(attendedId)+")",null);attendedId=null;}}
 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);attendedId=i.getStringExtra("attended_id");applyAttended();}
 @Override public void onBackPressed(){if(view.canGoBack())view.goBack();else super.onBackPressed();}
}
